INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (1, "あら、タマキさんじゃない。\nこんなところで何やってるの？", 0, 0, 944, 19440030, 10, 1, 11, 126811, 0);
