INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (1, "なんだ、ユカリだったかにゃ。\n何ってもちろん商売にゃ！", 0, 0, 944, 19440033, 10, 1, 11, 107911, 0);
